contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 burnValue) public {
        // Bound burnValue to be <= initial balances[owner] = totalDistributed = 250000000e18
        vm.assume(burnValue > 0 && burnValue <= 250000000e18);

        // Get initial totalDistributed
        uint256 initialTotalDistributed = c.totalDistributed();

        // Call burn (onlyOwner) with prank
        vm.prank(c.owner());
        // Owner must have sufficient balance for burn; owner initial balance = totalDistributed
        c.burn(burnValue);

        // Now call NETM()
        vm.prank(c.owner());
        c.NETM();

        // After NETM(), totalDistributed should be initialTotalDistributed - burnValue
        // (Because NETM sets totalDistributed = totalDistributed, but in the reference, burn decreases totalDistributed, so after NETM, it should reflect that decrease)
        // More precisely: NETM() sets balances[owner] = totalDistributed, but does not change totalDistributed itself.
        // So the expected post-NETM totalDistributed = initialTotalDistributed - burnValue (since burn reduced it)
        // Note: The reference contract's burn decreases totalDistributed by _value. So after burn, totalDistributed = initial - burnValue. Then NETM() doesn't change totalDistributed, so final = initial - burnValue.
        // The mutant's burn does NOT decrease totalDistributed, so after burn, totalDistributed = initial. Then NETM() doesn't change, so final = initial.
        // The rule: after NETM(), totalDistributed == initialTotalDistributed - burnValue.

        uint256 postTotalDistributed = c.totalDistributed();
        assertTrue(postTotalDistributed == initialTotalDistributed - burnValue, "totalDistributed not decreased by burn after NETM");
    }
}

